 float la=abs(u.y),belt=.03*(1.-smoothstep(.0,.16,la))-.05*smoothstep(.16,.26,la)*(1.-smoothstep(.5,.62,la))+.02*smoothstep(.66,.8,la)*(1.-smoothstep(.9,.97,la));
