  float m=h3(ci+9.),br=.25+2.2*pow(m,5.);if(br<=1.2)continue;vec3 j=vec3(h3(ci+3.1),h3(ci+7.7),h3(ci+1.3)),sd=normalize((ci+.3+j*.4)/90.);
