float pn(vec3 x,float P){vec3 i=floor(x),f=fract(x);f=f*f*(3.-2.*f);
 return mix(mix(mix(hp(i,P),hp(i+vec3(1,0,0),P),f.x),mix(hp(i+vec3(0,1,0),P),hp(i+vec3(1,1,0),P),f.x),f.y),
