vec3 trL(float r,float mu){if(r>=uAR)return vec3(1.);float H=sqrt((uAR-uPR)*(uAR+uPR)),rho=sqrt(max((r-uPR)*(r+uPR),0.)),c=(uAR-r)*(uAR+r),s=sqrt(max(c+r*r*mu*mu,0.));
