vec4 wRow(int j,int ix,vec3 w){return texelFetch(uWorld,ivec2((ix+2047)%1024,j),0)*w.x+texelFetch(uWorld,ivec2((ix+2048)%1024,j),0)*w.y+texelFetch(uWorld,ivec2((ix+2049)%1024,j),0)*w.z;}
vec4 wTexUV(vec2 u0){vec2 uv=u0*vec2(1024.,512.)-.5,c=floor(uv+.5),t=uv-c;int ix=int(c.x),iy=int(c.y);
