void main(){vec2 q=vNdc;vec3 d=uFace==0?vec3(1.,-q.y,-q.x):uFace==1?vec3(-1.,-q.y,q.x):uFace==2?vec3(q.x,1.,q.y):uFace==3?vec3(q.x,-1.,-q.y):uFace==4?vec3(q.x,-q.y,1.):vec3(-q.x,-q.y,-1.);
